param([Parameter(Mandatory=$true,ParameterSetName='Package')][string]$PackageRoot,[Parameter(Mandatory=$true,ParameterSetName='Installer')][string]$InstallerPath,[Parameter(Mandatory=$true)][ValidatePattern('^[A-Fa-f0-9]{40}$')][string]$CertificateThumbprint,[Parameter(Mandatory=$true)][uri]$TimestampServer)
$ErrorActionPreference='Stop'
if($TimestampServer.Scheme -notin @('http','https')){throw 'A certificate-provider timestamp service URL is required.'}
$certificate=Get-Item -LiteralPath ('Cert:\CurrentUser\My\'+$CertificateThumbprint)
if(-not $certificate.HasPrivateKey -or $certificate.NotAfter -le (Get-Date) -or $certificate.Subject -eq $certificate.Issuer -or @($certificate.EnhancedKeyUsageList|Where-Object{$_.ObjectId -eq '1.3.6.1.5.4.2.7.3.3'}).Count -ne 1){throw 'A current CA-issued code-signing certificate with its private key is required.'}
$chain=[Security.Cryptography.X509Certificates.X509Chain]::new();try{if(-not $chain.Build($certificate)){throw 'The publisher certificate chain is not trusted.'}}finally{$chain.Dispose()}
if($InstallerPath){$result=Set-AuthenticodeSignature -LiteralPath ([IO.Path]::GetFullPath($InstallerPath)) -Certificate $certificate -HashAlgorithm SHA256 -TimestampServer $TimestampServer.AbsoluteUri;if($result.Status -ne 'Valid'){throw 'Installer signature did not validate.'};Write-Output 'Installer publisher signature verified.';return}
$root=[IO.Path]::GetFullPath($PackageRoot);$files=@(Get-Item -LiteralPath (Join-Path $root 'CodexLiveBackground.exe'),(Join-Path $root 'startup\DreamSkinPortHook.exe'))+@(Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.ps1')
foreach($file in $files){$result=Set-AuthenticodeSignature -LiteralPath $file.FullName -Certificate $certificate -HashAlgorithm SHA256 -TimestampServer $TimestampServer.AbsoluteUri;if($result.Status -ne 'Valid'){throw ('Signature verification failed: '+$file.Name)}}
$compatibility=Join-Path $root 'service-compatibility.json';$profiles=[IO.File]::ReadAllText($compatibility)|ConvertFrom-Json;$hashes=@{};foreach($name in @('DreamSkinPortHook.exe','monitor-skin.ps1','register-port.ps1')){$hashes[$name]=(Get-FileHash -LiteralPath (Join-Path $root ('startup\'+$name))).Hash};$profiles.profiles=@($profiles.profiles)+@(@{name=('signed-1.5.4.2-'+$CertificateThumbprint);hashes=$hashes});[IO.File]::WriteAllText($compatibility,($profiles|ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
# Signing changes bytes, so refresh all manifest entries after signatures exist.
$manifestPath=Join-Path $root 'manifest.json';$manifest=[IO.File]::ReadAllText($manifestPath)|ConvertFrom-Json
foreach($entry in $manifest.files){$file=Get-Item -LiteralPath (Join-Path $root $entry.path);$entry.bytes=$file.Length;$entry.sha256=(Get-FileHash -LiteralPath $file.FullName).Hash}
[IO.File]::WriteAllText($manifestPath,($manifest|ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false))
Write-Output 'Publisher signatures verified; no certificate was installed or security setting changed.'
